import{c as a,Q as n,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/zh-cn_formulaimage_0000002192017270.DqEO12Zc.png",i="/assets/zh-cn_formulaimage_0000002192023094.CoAEZnm3.png",f=JSON.parse('{"title":"Sin","description":"","frontmatter":{},"headers":[{"level":1,"title":"Sin","slug":"sin"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/数学计算/Sin接口/Sin.md","filePath":"api/SIMD-API/高阶API/数学计算/Sin接口/Sin.md"}'),p={name:"api/SIMD-API/高阶API/数学计算/Sin接口/Sin.md"};function o(r,s,d,c,h,u){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="sin" tabindex="-1">Sin <a class="header-anchor" href="#sin" aria-label="Permalink to &quot;Sin&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按元素做正弦函数计算，计算公式如下：</p><p><img src="'+l+'" alt=""></p><p>Sin(x)的泰勒展开式为：</p><p><img src="'+i+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><ul><li><p>源操作数Tensor全部/部分参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, bool isReuseSource = false, const SinConfig&amp; config = defaultSinConfig&gt;</span></span>
<span class="line"><span>__aicore__ inline void Sin(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const uint32_t calCount)</span></span></code></pre></div></li><li><p>源操作数Tensor全部参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, bool isReuseSource = false, const SinConfig&amp; config = defaultSinConfig&gt;</span></span>
<span class="line"><span>__aicore__ inline void Sin(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer)</span></span></code></pre></div></li></ul></li><li><p>接口框架申请临时空间</p><ul><li><p>源操作数Tensor全部/部分参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, bool isReuseSource = false, const SinConfig&amp; config = defaultSinConfig&gt;</span></span>
<span class="line"><span>__aicore__ inline void Sin(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const uint32_t calCount)</span></span></code></pre></div></li><li><p>源操作数Tensor全部参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, bool isReuseSource = false, const SinConfig&amp; config = defaultSinConfig&gt;</span></span>
<span class="line"><span>__aicore__ inline void Sin(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor)</span></span></code></pre></div></li></ul></li></ul><p>由于该接口的内部实现中涉及复杂的数学计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持开发者<strong>通过sharedTmpBuffer入参传入</strong>和<strong>接口框架申请</strong>两种方式。</p><ul><li><p>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</p></li><li><p>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li></ul><p>接口框架申请的方式，开发者需要预留临时空间；通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间。临时空间大小BufferSize的获取方式，通过<a href="./GetSinMaxMinTmpSize.html">GetSinMaxMinTmpSize</a>接口获取需要预留空间的范围大小。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isReuseSource</td><td>是否允许修改源操作数，默认值为false。该参数仅在输入的数据类型为float时生效。 true：开发者允许源操作数被改写，可以使能该参数，使能后本接口内部计算时复用srcTensor的内存空间，节省部分内存空间；false：本接口内部计算时不复用srcTensor的内存空间。</td></tr><tr><td>config</td><td>该参数仅支持Ascend 950PR/Ascend 950DT。 Sin算法的相关配置。此参数可选配，SinConfig类型，具体定义如下方代码所示，其中参数的含义为： algo：Sin内部实现使用的算法。SinAlgo类型，支持的取值如下：POLYNOMIAL_APPROXIMATION：默认值。该算法通过简单的多项式逼近实现Sin接口，支持的输入值域范围为[-65504.0, 65504.0]，支持的数据类型为half、float。RADIAN_REDUCTION：该算法通过完整的周期约减实现Sin接口，支持输入全值域，支持的数据类型为half、float。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct SinConfig {</span></span>
<span class="line"><span>  SinAlgo algo = SinAlgo::POLYNOMIAL_APPROXIMATION;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>enum class SinAlgo {</span></span>
<span class="line"><span>  POLYNOMIAL_APPROXIMATION = 0;</span></span>
<span class="line"><span>  RADIAN_REDUCTION;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 用于Sin内部复杂计算时存储中间变量，由开发者提供。 临时空间大小BufferSize的获取方式请参考GetSinMaxMinTmpSize。</td></tr><tr><td>calCount</td><td>输入</td><td>参与计算的元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>对于Ascend 950PR/Ascend 950DT，模板参数config中使用多项式拟合算法POLYNOMIAL_APPROXIMATION时，必须保证输入源数据的值域在[-65504.0, 65504.0]范围内。</p></li><li><p>对于以下产品，输入源数据必须保持值域在[-65504.0, 65504.0]范围内。</p><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li><li>Atlas 推理系列产品AI Core</li></ul></li><li><p><strong>不支持源操作数与目的操作数地址重叠。</strong></p></li><li><p>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</p></li><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放Sin计算结果的Tensor</span></span>
<span class="line"><span>// srcLocal: 存放Sin计算输入的Tensor</span></span>
<span class="line"><span>// sharedTmpBuffer: 存放Sin计算过程中临时缓存的Tensor</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 接口框架申请临时空间，全部参与计算</span></span>
<span class="line"><span>AscendC::Sin(dstLocal, srcLocal);</span></span>
<span class="line"><span>// 接口框架申请临时空间，部分参与计算, 需要参与计算的元素个数为512</span></span>
<span class="line"><span>AscendC::Sin(dstLocal, srcLocal, 512);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间，全部参与计算</span></span>
<span class="line"><span>AscendC::Sin(dstLocal, srcLocal, sharedTmpBuffer);</span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间，部分参与计算, 需要参与计算的元素个数为512</span></span>
<span class="line"><span>AscendC::Sin(dstLocal, srcLocal, sharedTmpBuffer, 512);</span></span>
<span class="line"><span>constexpr AscendC::SinAlgo algo = AscendC::SinAlgo::RADIAN_REDUCTION;</span></span>
<span class="line"><span>constexpr AscendC::SinConfig config = { algo };</span></span>
<span class="line"><span>AscendC::Sin&lt;half, false, config&gt;(dstLocal, srcLocal, sharedTmpBuffer, 512);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal): </span></span>
<span class="line"><span>[-2.56 -2.55 -2.54 ... 0. ... 2.53  2.54  2.55]</span></span>
<span class="line"><span>输出数据(dstLocal): </span></span>
<span class="line"><span>[-0.54889839 -0.55703507 -0.56672889 ... 0. 0.57474768 0.56672889 0.55703507]</span></span></code></pre></div>`,27)])])}const T=a(p,[["render",o]]);export{f as __pageData,T as default};
